\label{T.A}   
There exists a forcing extension in which for every countable theory~$T$ that has the robust order property the following holds. 

For every sequence  $(A_n)$ of countable structures in the language of $T$, every sequence $(B_n)$ of countable models of~$T$, and every nonprincipal ultrafilter $\mathcal U$ on~${\mathbb N}$, the following are true.  
\begin{enumerate}
\item \label{1.T.A} The ultraproduct $\prod_{\mathcal U} B_n$ is not isomorphic to $\prod_{\operatorname{Fin}} A_n$ or even to an elementary submodel thereof. 	
\item \label{3.T.A} If the order property of $T$ is witnessed  by a quantifier-free formula then $\prod_{\mathcal U} B_n$  does not embed into $\prod_{\operatorname{Fin}} A_n$. 
\end{enumerate}

\label{C.D}
	There exists a forcing extension in which the following holds for  every separable \textrm{$C^*$}-algebra $A$ and every ultrafilter $\mathcal U$ on ${\mathbb N}$. 
\begin{enumerate}
\item	 $(A\otimes C(K))^{\mathcal U} $ is not isomorphic to $A^\infty$. 
\item  $(A\otimes C(K))^{\mathcal U}$ is not  isomorphic to a \textrm{$C^*$}-subalgebra of $B^\infty$ for any separable \textrm{$C^*$}-algebra $B$.  
	\end{enumerate}

\label{Def.T.leqp} Suppose that $T$ is a first-order theory, not necessarily complete. 
\begin{enumerate}
\item 	If $\varphi(\bar x,\bar y)$ is an asymmetric  formula (with $\bar x$ and $\bar y$ of the same sort) in the language of $T$ consider the asymmetric binary relation $\triangleleft_\varphi$ on a model $A$ of $T$, defined by 
\begin{equation}
\bar a\triangleleft_\varphi \bar b\text{ if }A\models \varphi(\bar a, \bar b). 
\end{equation}
Some $\bar a_j$, for $j<n$, in $A$ form a  \emph{$\triangleleft_\varphi$-chain} if for all $i\neq j$ we have $\bar a_i\triangleleft_\varphi \bar a_j$ if and only if~$i<j$. 
\item If every model of $T$ has an arbitrarily long finite $\triangleleft_\varphi$-chain, we say that the pair \emph{$(T,\varphi)$ has 
the order property, OP} (\cite{Sh:c}).\footnote{One  says that $\varphi$ has the order property when $T$ is clear from the context.} 
\item The pair $(T,\varphi)$ has the \emph{robust order property} if it has the order property and in addition for models $A_n$, for $n\in {\mathbb N}$, of $T$ and $\bar a$ and~$\bar b$ in $\prod_{\operatorname{Fin}} A_n$ we have $\prod_{\operatorname{Fin}} A_n\models \varphi(\bar a, \bar b)$ if and only if the set 
\[
\{n\mid A_n\not\models \varphi(\bar a_n, \bar b_n)\}
\]
is finite. (Note that it is not required that $\prod_{\operatorname{Fin}} A_n$ models  $T$.)
\item The pair $(T,\varphi)$ is said to have the \emph{strict order property} (SOP) if 
the relation $\triangleleft_\varphi$ is a partial ordering on every model of $T$. 
\end{enumerate}

\label{L.universal} 
There exists an injectively universal countable structure $(C,\triangleleft)$ with an asymmetric  binary relation $\triangleleft$. 
This universality property is absolute between transitive models of a sufficiently large fragment of $\operatorname{ZFC}$.

\label{Def.depletion}\label{Def.llS}
Suppose that $I$ is a finite linear ordering whose elements are listed in the increasing order as $\xi(i)$, for $i<m$ and $m=|I|\geq 2$.\footnote{If this appears excessively pedantic, note that the conditions \eqref{2.2.depletion} and \eqref{3.2.depletion} below are sensitive to leaving gaps in $I$. We note that $I$ is not necessarily a set of ordinals.}  Also suppose $A$ and $F(\xi)$, for $\xi\in I$, are disjoint sets, and 
$\leq$ is a partial ordering on a set that includes  $E:=A\cup \bigcup_{\xi\in I} F(\xi)$.  Define a binary relation $\ll_I$ on~$E$ as follows.

If $x$ and $y$ belong to $E$, we let $x\ll_I y$ if and only $x\leq y$ and in addition  one of the following applies. 
\begin{enumerate}
\item \label{1.depletion} Both $x$ and $y$ belong to $A\cup F(\xi)$ for some $\xi\in I$.  
\item \label{2.depletion} There are $i<j$ such that  $x\in F(\xi(i))$ and $y\in F(\xi(j))$ and  one of the following holds.  
\begin{enumerate}
\item \label{2.1.depletion} There exists $a\in A$ such that $x\leq a$ and $a\leq y$ 	
\item\label{2.2.depletion}  With $k=j-i$,  there are $x_l\in F(\xi(i+l))$ for $0\leq l \leq k$ such that $x_0=x$, $x_k=y$, and $x_l\leq x_{l+1}$ for all $l<k$.
\end{enumerate}
\item \label{3.depletion} There are $i>j$ such that  $x\in F(\xi(i))$ and $y\in F(\xi(j))$ and  one of the following holds.  
\begin{enumerate}
\item There exists $a\in A$ such that $x\leq a$ and $a\leq y$ 	
\item \label{3.2.depletion} With $k=i-j$,  there are $x_l\in F(\xi(j+l))$ for $0\leq l \leq k$ such that $x_0=y$, $x_k=x$, and $x_l\geq x_{l+1}$ for all $l<k$.  
\end{enumerate}
\end{enumerate}
 The elements $x_i$, for $i\leq k$ as in \eqref{2.2.depletion} or \eqref{3.2.depletion} comprise an \emph{$I$-walk between $x$ and $y$}, or an \emph{$I$-walk with endpoints $x$ and $y$}. The relation $\ll_I$ is called the \emph{depletion of $\leq$ given by $I$, $A$, and $(F(\xi)\vert \xi\in I )$}. When $I$ is clear from the context, we write $\ll$ for $\ll_I$.

\label{C.314}
Suppose that $\kappa$ is an uncountable cardinal, $A$ and $F(\xi)$, for $\xi<\kappa$, are disjoint, and  $\leq$ is a partial ordering of $E:=A\cup\bigcup_{\xi<\kappa} F(\xi)$. In addition suppose that $A$ is countable, all $F(\xi)$ are finite, and $E$ has neither $\kappa$ nor $\kappa^*$-chains. 

Then there exists a cofinal $X\subseteq \kappa$ such that  for any two distinct elements $\xi$ and $\eta$ of $X$ the following condition holds. 
\begin{enumerate}
\item[$*_{(\xi,\eta)}$] there is $s\Subset \kappa$ such that $\{\xi,\eta\}=\{\min(s), \max(s)\}$ and there is no $s$-walk with endpoints in  $F(\xi)$ and $F(\eta)$.\footnote{We emphasize that $s$ is not necessarily a subset of $X$.}  	
\end{enumerate}

\label{L.compatible} Suppose that $E$ is a poset,  $R\Subset E$,  $m\geq 2$ and  $p_i$, for $i<m$, are conditions in $\mathbb H_E$
such that the following holds whenever $i\neq j$. 
\begin{enumerate}
	\item  We have   $D_i\cap D_j=R$. 
	\item  All $a\in R$ satisfy 
$f_i(a)\restriction \min(n_i, n_j)= f_j(a)\restriction \min(n_i,n_j)$. 
\end{enumerate}
Then some $q\in \mathbb H_E$ extends all $p_i$.\footnote{We write $q\leq p$ if $q$ extends $p$.}

\label{L.HE.product} Suppose $(E,\leq)$ is a poset and $A, B$, and $D$ are subsets of $E$ such that $E=A\cup B$, $D=A\cap B$, and for every $a\in A$ and every  $b\in B$ the following conditions hold.  
\begin{enumerate}
\item $a\leq b$ if and only if $a\leq d$ and $d\leq b$ for some $d\in D$, and
\item   $a\geq b$ if and only if $a\geq d$ and $d\geq b$ for some $d\in D$. 
\end{enumerate}
Then $\mathbb H_D$ forces that  ($\dot G$ is the canonical name for the generic filter in~$\mathbb H_D$) $\mathbb H_E(D,\Upsilon_{\dot G})$ and $\mathbb H_A(D,\Upsilon_{\dot G})\times 	\mathbb H_B(D,\Upsilon_{\dot G})$ are forcing equivalent.

We use  the notation from Lemma~\ref{L.quotient} and write $\dot G(X)$ for the canonical name for the generic filter for $\mathbb H_X$ (or $\mathbb H_X(Y,\Upsilon)$ for some $Y$ and $\Upsilon$) where $X$ is $A,B,D$, or $E$. 


By Lemma~\ref{L.quotient} \eqref{1.L.quotient}  with $E$ and $A$ in place of $E'$ and $E$, $\mathbb H_E$ is forcing equivalent to $\mathbb H_A* \mathbb H_E(A,\Upsilon_{\dot G(A)})$.  By the same lemma with $A$ and $D$ in place of $E'$ and $E$, $\mathbb H_A$ is forcing equivalent to $\mathbb H_D* \mathbb H_A(D,\Upsilon_{\dot G(D)})$. Therefore $\mathbb H_E$ is forcing equivalent to the iteration 
\begin{equation}\label{Eq.iteration}
\mathbb H_D*\mathbb H_A(D,\Upsilon_{\dot G(D)})*\mathbb H_E(A,\Upsilon_{\dot G(A)}).
\end{equation}
 The assumptions imply that	$L(b)\cap D$ is cofinal in $L(b)$ and $R(b)\cap D$ is coinitial in $R(b)$, for every $b\in B$. 
Therefore by Lemma~\ref{L.quotient} \eqref{3.L.quotient} applied with  $\mathbb H_E(A,\Upsilon_{\dot G(D)})$,   $E$, $A$, and $D$ in place of $\mathbb H_{E'}(E,\Upsilon_{\dot G})$, $E'$, $E$, and~$X$, we conclude that $\mathbb H_A$ forces that   $\mathbb H_E(A,\Upsilon_{\dot G(A)})$ is forcing equivalent to $\mathbb H_B(D,\Upsilon_{\dot G(D)})$ (also recall that $\mathbb H_D$ is a regular subordering of $\mathbb H_A$, and that $\Upsilon_{G(A)}$ extends~$\Upsilon_{G(D)}$).   
Since $\mathbb H_B(D,\Upsilon_{\dot G(D)})$ does not depend on $\dot G(A)$, but only on its intersection with $\mathbb H_D$, the   iteration in~\eqref{Eq.iteration} is forcing equivalent to 
\begin{equation*}
\mathbb H_D*(\mathbb H_B(D,\Upsilon_{\dot G(D)})\times \mathbb H_A(A,\Upsilon_{\dot G(D)}))
\end{equation*}
and $\mathbb H_D$ forces that $\mathbb H_E(A,\Upsilon_{\dot G(A)})$ is forcing equivalent to the product of   $\mathbb H_B(D,\Upsilon_{\dot G(D)})$ and $\mathbb H_A(A,\Upsilon_{\dot G(D)})$, as claimed.

\label{T.no.kappa.chains}
		 Suppose $\kappa$ is a regular cardinal such that $\lambda^{\aleph_0}<\kappa$ for every cardinal $\lambda<\kappa$  
		 and $E$ is a partial ordering such that neither $\kappa$ nor $\kappa^*$ embeds into $E$. Then $\mathbb H_E$ forces that  $\prod_{\operatorname{Fin}} (A_n, \triangleleft_n)$ has no $\kappa$-chains  
		 for any sequence  $(A_n,\triangleleft_n)$, for $n\in {\mathbb N}$, 
		  of countable sets with asymmetric binary relations.

\label{P.HE.embeds}
	Suppose that the pair $(T,\varphi)$ has the robust order property and $E$ is any poset. Then $\mathbb H_E$ forces the following. 
\begin{enumerate}
\item  The poset  $E$ embeds into $\prod_{\operatorname{Fin}} (A_n, \triangleleft_\varphi)$ for every sequence $(A_n)$ of models of $T$. 
\item For any nonprincipal ultrafilter $\mathcal U$ on ${\mathbb N}$ there is strictly increasing map from $E$ into $\prod_{\mathcal U} (A_n,\triangleleft_\varphi)$ whose range is linearly ordered by $\triangleleft_\varphi$.  
\end{enumerate}

The first part is almost obvious, but proving it in some detail will also provide a proof of the second part.  

By Lemma~\ref{L.strictly.increasing}, there are $\eta\in {\mathbb N}^{{\mathbb N}}$ and  $\Phi\colon \prod_{\operatorname{Fin}} (n,\leq^*)\to \prod_{\operatorname{Fin}} (\eta(n),<^*)$ such that $f\leq^* g$ and $g\nleq^* f$ implies $(\forall^\infty n) \Phi(f)(n)<\Phi(g)(n)$. Since $A_n$ is a model of $T$, there exists a $\triangleleft_\varphi$-chain $C_n$ of length $\eta(n)$ in $A_n$. By  identifying this chain with $(\eta(n),\leq)$, we obtain $\Phi\colon \prod_{\operatorname{Fin}} (n, \leq^*)\to\prod_{\operatorname{Fin}} (A_n,\triangleleft_\varphi)$ such that $f\leq^* g$ and $g\nleq^* f$ implies  $\Phi(f)(n)\triangleleft_\varphi \Phi(g)(n)$ and $\Phi(g)(n)\ntriangleleft_\varphi \Phi(f)(n)$ for all but finitely many $n$. By composing the embedding of $E$ into $\prod_{\operatorname{Fin}} (n,\leq^*)$ provided by Theorem~\ref{T.HE} with $\Phi$,  we obtain  an $\mathbb H_E$-name  for an embedding of $\Xi\colon E\to \prod_{\operatorname{Fin}} (A_n,\triangleleft_\varphi)$ (this proves the first part; read on for the proof of the second part) that in addition has the property that $a<_E b$  implies
  \begin{equation*}
  (\forall^\infty n)(\Xi(f)(n)\triangleleft_\varphi \Xi(g)(n)\text{ and }\Xi(g)(n)\ntriangleleft_\varphi \Xi(f)(n)).
    \end{equation*}
Let $\mathcal U$ be a nonprincipal ultrafiter on ${\mathbb N}$ and let $\pi_{\mathcal U}$ denote the quotient map from $\prod_{\operatorname{Fin}} A_n$ to $\prod_{\mathcal U} A_n$. Then the displayed formula  implies that the restriction of $\pi_{\mathcal U}$ to  $\Xi[E]$ is strictly increasing. The range of this map is the ultraproduct of the $\triangleleft_\varphi$-chains $C_n$, and therefore linearly ordered by \L o\'s's Theorem.   This proves the second part.

\label{P.tie}
Suppose $\mathfrak B$ is a Boolean algebra. 
The following are equivalent for 
an ultrafilter $\mathcal U$ on $\mathfrak B$. 
 \begin{enumerate}
 \item The complement of $\mathcal U$ is equal to the union of two orthogonal ideals.
 \item \label{2.P.tie} $\mathcal U$ is a tie-point in the Stone space of $\mathfrak B$. \qed 
 \end{enumerate}

By analogy with true P-points, 
  an ultrafilter $\mathcal U$ in a Boolean algebra  is called a \emph{true tie point}
  if the ideals as in Proposition~\ref{P.tie} \eqref{2.P.tie} 
  can be chosen so that each one of them is generated by a linearly ordered subset.

\label{P.SOP4} 
	 Suppose that $T$ is a  theory in a countable language with the SOP$_4$. If there exists a cardinal $\kappa$ such that $\kappa^+<\mathfrak c=\operatorname{cf}(\mathfrak c)<2^\kappa$ and $T$ is complete, then $\operatorname{Ult}_T$ does not have a $\preceq$-universal model. 

If the SOP$_4$ is witnessed by a quantifier-free formula, then even if $T$ is not complete,  $\operatorname{Ult}_T$ does not even have a $\hookrightarrow$-universal model.
